class RedirectServer:
    def __init__(self):
        self.httpd = None
        self.thread = None
        self.running = False

    def start(self):
        if self.running:
            return
        # If Apache or other webserver is installed, let it handle port 80 and virtual hosts
        if os.path.exists("/www/server/apache/bin/httpd") or os.path.exists("/etc/init.d/httpd") or os.path.exists("/usr/sbin/apache2") or os.path.exists("/usr/sbin/nginx"):
            return
        self.running = True
        self.thread = threading.Thread(target=self._run, daemon=True)
        self.thread.start()

    def _run(self):
        from http.server import HTTPServer, BaseHTTPRequestHandler
        from socketserver import ThreadingMixIn
        import socket, select

        class ThreadedHTTPServer(ThreadingMixIn, HTTPServer):
            daemon_threads = True
            allow_reuse_address = True

        class RedirectHandler(BaseHTTPRequestHandler):
            def _proxy_to_ws(self):
                try:
                    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                    s.settimeout(5)
                    s.connect(('127.0.0.1', 8888))
                    s.settimeout(None)
                    raw_req = f"{self.command} {self.path} {self.request_version}\r\n"
                    for k, v in self.headers.items():
                        raw_req += f"{k}: {v}\r\n"
                    raw_req += "\r\n"
                    s.sendall(raw_req.encode("utf-8"))

                    self.connection.setblocking(False)
                    s.setblocking(False)
                    socks = [self.connection, s]
                    while True:
                        r, _, x = select.select(socks, [], socks, 120)
                        if x or not r:
                            break
                        for sock in r:
                            other = s if sock is self.connection else self.connection
                            data = sock.recv(16384)
                            if not data:
                                return
                            other.sendall(data)
                except Exception:
                    pass
                finally:
                    try:
                        s.close()
                    except Exception:
                        pass

            def do_GET(self):
                upgrade = self.headers.get('Upgrade', '').lower()
                path = (self.path or '').lower()
                if upgrade == 'websocket' or path.startswith('/ssh') or path.startswith('/ws'):
                    return self._proxy_to_ws()

                host = self.headers.get('Host', '')
                if ':' in host:
                    host = host.split(':')[0]
                port = get_panel_port()
                self.send_response(301)
                self.send_header('Location', f'https://{host}:{port}{self.path}')
                self.end_headers()

            def do_CONNECT(self):
                return self._proxy_to_ws()

            def do_POST(self):
                upgrade = self.headers.get('Upgrade', '').lower()
                path = (self.path or '').lower()
                if upgrade == 'websocket' or path.startswith('/ssh') or path.startswith('/ws'):
                    return self._proxy_to_ws()
                self.send_error(405, "Method Not Allowed")

            def log_message(self, format, *args):
                pass

        while self.running:
            try:
                self.httpd = ThreadedHTTPServer(('0.0.0.0', 80), RedirectHandler)
                self.httpd.serve_forever()
            except OSError:
                self.running = False
                break
            except Exception:
                time.sleep(2)

    def stop(self):
        self.running = False
        if self.httpd:
            try:
                self.httpd.shutdown()
                self.httpd.server_close()
            except Exception:
                pass
            self.httpd = None
        if self.thread:
            self.thread.join(timeout=2)
            self.thread = None

