@app.route("/api/protocols/advanced_logs/<protocol>", methods=["GET"])
def api_protocols_advanced_logs(protocol):
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    
    protocol = (protocol or "").lower()
    services = []
    if protocol in ["ssh", "sshd"]: services = ["mhpanel-ssh", "ssh-ws", "sshd_vpn", "ssh", "sshd"]
    elif protocol in ["openvpn", "openvpn-server"]: services = ["openvpn-server@server", "openvpn-server@server-tcp", "openvpn@server", "openvpn@server-tcp"]
    elif protocol == "ocserv": services = ["ocserv"]
    elif protocol in ["ikev2", "strongswan", "ipsec"]: services = ["strongswan-starter", "strongswan", "strongswan-swanctl"]
    elif protocol in ["sstp", "sstpd"]: services = ["sstpd", "accel-ppp", "vpnserver"]
    elif protocol in ["l2tp", "xl2tpd"]: services = ["xl2tpd"]
    elif protocol in ["pptp", "pptpd"]: services = ["pptpd", "mhpanel-pptp"]
    elif protocol == "badvpn": services = ["videocall", "badvpn"]
    elif protocol in ["wireguard", "wg"]: services = ["wg-quick@wg0"]
    elif protocol in ["amneziawg", "awg"]: services = ["awg-quick@awg0"]
    elif protocol == "mtproto": services = ["mhpanel-mtproto*"]
    elif protocol in ["freeradius", "radius"]: services = ["freeradius"]
    else:
        services = get_service_names(protocol)
        if not services:
            return jsonify({"error": "Unknown protocol"}), 400
    
    if protocol in ["ikev2", "strongswan", "ipsec"]:
        cmd = [
            "journalctl",
            "_SYSTEMD_UNIT=strongswan-starter.service",
            "+", "_SYSTEMD_UNIT=strongswan.service",
            "+", "_SYSTEMD_UNIT=strongswan-swanctl.service",
            "+", "SYSLOG_IDENTIFIER=charon",
            "+", "_COMM=charon",
            "-n", "600", "--no-pager", "-o", "json"
        ]
    elif protocol in ["l2tp", "xl2tpd"]:
        cmd = [
            "journalctl",
            "_SYSTEMD_UNIT=xl2tpd.service",
            "+", "SYSLOG_IDENTIFIER=xl2tpd",
            "+", "_COMM=xl2tpd",
            "+", "SYSLOG_IDENTIFIER=pppd",
            "+", "_COMM=pppd",
            "-n", "600", "--no-pager", "-o", "json"
        ]
    elif protocol in ["pptp", "pptpd"]:
        cmd = [
            "journalctl",
            "_SYSTEMD_UNIT=pptpd.service",
            "+", "SYSLOG_IDENTIFIER=pptpd",
            "+", "_COMM=pptpd",
            "+", "SYSLOG_IDENTIFIER=pppd",
            "+", "_COMM=pppd",
            "-n", "600", "--no-pager", "-o", "json"
        ]
    elif protocol in ["sstp", "sstpd"]:
        cmd = [
            "journalctl",
            "_SYSTEMD_UNIT=sstpd.service",
            "+", "SYSLOG_IDENTIFIER=sstpd",
            "+", "_COMM=sstpd",
            "+", "SYSLOG_IDENTIFIER=pppd",
            "+", "_COMM=pppd",
            "+", "_SYSTEMD_UNIT=accel-ppp.service",
            "-n", "600", "--no-pager", "-o", "json"
        ]
    else:
        cmd = ["journalctl"]
        for svc in services:
            cmd.extend(["-u", svc])
        cmd.extend(["-n", "300", "--no-pager", "-o", "json"])
    
    try:
        res = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
        logs = []
        for line in res.stdout.strip().split('\n'):
            if not line: continue
            try:
                j = json.loads(line)
                timestamp = int(j.get("__REALTIME_TIMESTAMP", 0)) / 1000000
                message = j.get("MESSAGE", "")
                priority = int(j.get("PRIORITY", 6))
                ident = j.get("SYSLOG_IDENTIFIER", "")
                
                if isinstance(message, list):
                    try:
                        message = bytes(message).decode('utf-8', 'ignore')
                    except:
                        message = str(message)
                
                # Filter out frequent internal vici client polling noise from web panel
                if protocol in ["ikev2", "strongswan", "ipsec"] and ("vici client" in message or "registered for: list-sa" in message):
                    continue

                if ident and ident in ["pppd", "xl2tpd", "pptpd", "sstpd", "charon"] and not message.startswith(f"[{ident}]"):
                    message = f"[{ident}] {message}"

                logs.append({
                    "timestamp": timestamp,
                    "message": message,
                    "priority": priority
                })
            except Exception:
                pass
        return jsonify({"logs": logs})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

# --- MH Panel Internal FreeRADIUS & Unified Multi-Protocol Management ---
RADIUS_USERS_FILE = "/www/wwwroot/mhpanel/radius_users.json"
RADIUS_GROUPS_FILE = "/www/wwwroot/mhpanel/radius_groups.json"
RADIUS_NAS_FILE = "/www/wwwroot/mhpanel/radius_nas.json"
FREERADIUS_USERS_FILE = "/etc/freeradius/3.0/mhpanel_users"

def get_radius_nas_data():
    if os.path.exists(RADIUS_NAS_FILE):
        try:
            with open(RADIUS_NAS_FILE, "r") as f:
                data = json.load(f)
                if isinstance(data, list):
                    return data
        except Exception:
            pass
    return []

def sync_freeradius_nas():
    nas_list = get_radius_nas_data()
    conf_dir, _, service, user, group, _ = get_freeradius_info()
    os.makedirs(conf_dir, exist_ok=True)
    nas_conf_path = os.path.join(conf_dir, "mhpanel_nas.conf")
    
    lines = ["# MH Panel Managed Network Access Servers (MikroTik / Cisco / IBSng / Linux)\n\n"]
    for nas in nas_list:
        if not nas.get("active", True):
            continue
        nas_id = re.sub(r'[^a-zA-Z0-9_\-]', '_', str(nas.get("id") or nas.get("name") or "nas"))
        ip = nas.get("ip", "127.0.0.1").strip()
        secret = nas.get("secret", "testing123").strip()
        shortname = re.sub(r'[^a-zA-Z0-9_\-]', '_', nas.get("name", nas_id).strip())
        nas_type = nas.get("type", "other")
        
        lines.append(f"""client {nas_id} {{
    ipaddr = {ip}
    secret = {secret}
    shortname = {shortname}
    nas_type = {nas_type}
    require_message_authenticator = no
}}
""")
    
    try:
        with open(nas_conf_path, "w") as f:
            f.writelines(lines)
        import shutil
        shutil.chown(nas_conf_path, user=user, group=group)
        os.chmod(nas_conf_path, 0o640)
    except Exception:
        pass
        
    clients_conf = os.path.join(conf_dir, "clients.conf")
    if os.path.exists(clients_conf):
        try:
            with open(clients_conf, "r") as f:
                c_content = f.read()
            inc_line = f"$INCLUDE {nas_conf_path}"
            if inc_line not in c_content and "$INCLUDE /etc/freeradius/3.0/mhpanel_nas.conf" not in c_content and "$INCLUDE /etc/raddb/mhpanel_nas.conf" not in c_content:
                with open(clients_conf, "a") as f:
                    f.write(f"\n{inc_line}\n")
        except Exception:
            pass
            
    subprocess.run(["systemctl", "reload-or-restart", service], capture_output=True)

def save_radius_nas_data(nas_list):
    with open(RADIUS_NAS_FILE, "w") as f:
        json.dump(nas_list, f, indent=2)
    sync_freeradius_nas()

def get_freeradius_info():
    """
    Returns (conf_dir, users_file, service_name, rad_user, rad_group, auth_file)
    supporting Ubuntu/Debian (/etc/freeradius/3.0/) and RHEL/CentOS/AlmaLinux (/etc/raddb/).
    Ensures reciprocal symlinks so paths match across all distros.
    """
    if os.path.exists("/etc/freeradius/3.0"):
        conf_dir = "/etc/freeradius/3.0"
        auth_file = "/etc/freeradius/3.0/mods-config/files/authorize"
        service = "freeradius"
        user = "freerad"
        if not os.path.exists("/etc/raddb"):
            try: os.symlink("/etc/freeradius/3.0", "/etc/raddb")
            except Exception: pass
    elif os.path.exists("/etc/raddb"):
        conf_dir = "/etc/raddb"
        auth_file = "/etc/raddb/mods-config/files/authorize" if os.path.exists("/etc/raddb/mods-config/files/authorize") else "/etc/raddb/users"
        service = "radiusd"
        user = "radiusd"
        if not os.path.exists("/etc/freeradius/3.0"):
            try:
                os.makedirs("/etc/freeradius", exist_ok=True)
                os.symlink("/etc/raddb", "/etc/freeradius/3.0")
            except Exception: pass
    else:
        conf_dir = "/etc/freeradius/3.0"
        auth_file = "/etc/freeradius/3.0/mods-config/files/authorize"
        service = "freeradius"
        user = "freerad"
    
    users_file = os.path.join(conf_dir, "mhpanel_users")
    return conf_dir, users_file, service, user, user, auth_file

