@app.route("/api/wireguard/client/bulk", methods=["POST"])
def api_wg_client_bulk():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    prefix = request.json.get("prefix", "Client").strip()
    prefix = re.sub(r'[^a-zA-Z0-9_\-]', '', prefix)
    count = request.json.get("count", 1)
    limit_gb = request.json.get("limit_gb")
    expire_days = request.json.get("expire_days")
    start_on_first_connect = request.json.get("start_on_first_connect", False)
    group_name = str(request.json.get("group", "عمومی")).strip() or "عمومی"
    
    expire_date = None
    if expire_days and not start_on_first_connect:
        from datetime import datetime, timedelta
        expire_date = (datetime.now() + timedelta(days=int(expire_days))).strftime("%Y-%m-%d")
    try:
        count = int(count)
    except (ValueError, TypeError):
        count = 1
        
    if count < 1 or count > 50:
        return jsonify({"success": False, "error": "Count must be between 1 and 50"}), 400
        
    if not os.path.exists("/etc/wireguard/wg0.conf"):
        return jsonify({"success": False, "error": "WireGuard is not installed."}), 400
        
    settings = get_protocol_settings()
    wg_subnet = settings.get("wireguard_subnet", "10.13.0.0")
    subnet_prefix = wg_subnet.rsplit(".", 1)[0]
    
    with open("/etc/wireguard/wg0.conf", "r") as f:
        content = f.read()
        
    match_addr = re.search(r"^Address\s*=\s*(\d+\.\d+\.\d+)\.\d+", content, re.MULTILINE | re.IGNORECASE)
    if match_addr:
        subnet_prefix = match_addr.group(1)
        
    server_pubkey = ""
    if os.path.exists("/etc/wireguard/public.key"):
        with open("/etc/wireguard/public.key", "r") as f:
            server_pubkey = f.read().strip()
    if not server_pubkey and os.path.exists("/etc/wireguard/wg0.conf"):
        m = re.search(r"^PrivateKey\s*=\s*(.+)$", content, re.MULTILINE | re.IGNORECASE)
        if m:
            res_pk = subprocess.run(["wg", "pubkey"], input=m.group(1).strip(), capture_output=True, text=True)
            server_pubkey = res_pk.stdout.strip()
            if server_pubkey:
                with open("/etc/wireguard/public.key", "w") as f:
                    f.write(server_pubkey)
            
    port = get_active_port("wireguard") or 904
    
    server_ip = settings.get("wireguard_server_ip", "").strip() or get_server_domain() or get_server_public_ip()
    if ":" in server_ip and not (server_ip.startswith("[") and server_ip.endswith("]")):
        server_ip = get_server_public_ip()
            
    wg_dns1 = settings.get("wireguard_dns1", "8.8.8.8")
    wg_dns2 = settings.get("wireguard_dns2", "8.8.4.4")
    dns_val = f"{wg_dns1}, {wg_dns2}" if (wg_dns1 and wg_dns2) else (wg_dns1 or wg_dns2 or "8.8.8.8")
    
    escaped_prefix = subnet_prefix.replace(".", r"\.")
    used_ips = [int(ip) for ip in re.findall(escaped_prefix + r'\.(\d+)', content)]
    
    created_clients = []
    wg0_append_text = ""
    current_next_ip = 2
    
    for idx in range(1, count + 1):
        name = f"{prefix}-{idx}"
        while current_next_ip in used_ips:
            current_next_ip += 1
        if current_next_ip > 254:
            break
            
        client_ip = f"{subnet_prefix}.{current_next_ip}"
        used_ips.append(current_next_ip)
        
        privkey = subprocess.run(["wg", "genkey"], stdout=subprocess.PIPE, text=True).stdout.strip()
        pubkey = subprocess.run(["wg", "pubkey"], input=privkey, stdout=subprocess.PIPE, text=True).stdout.strip()
        
        wg0_append_text += f"\n# Name: {name}\n[Peer]\nPublicKey = {pubkey}\nAllowedIPs = {client_ip}/32\n"
        
        client_config = f"""[Interface]
PrivateKey = {privkey}
Address = {client_ip}/32
DNS = {dns_val}

[Peer]
PublicKey = {server_pubkey}
Endpoint = {server_ip}:{port}
AllowedIPs = 0.0.0.0/0
PersistentKeepalive = 25
"""
        sub_token = secrets.token_urlsafe(16)
        created_clients.append({
            "name": name,
            "ip": client_ip,
            "public_key": pubkey,
            "config": client_config,
            "group": group_name,
            "sub_token": sub_token
        })
        
    if wg0_append_text:
        with open("/etc/wireguard/wg0.conf", "a") as f:
            f.write(wg0_append_text)
        subprocess.run(f"wg syncconf wg0 <(wg-quick strip wg0)", shell=True, executable="/bin/bash")
        
    wg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/wg_users.json'):
        with open('/www/wwwroot/mhpanel/wg_users.json', 'r') as f:
            try: wg_users = json.load(f)
            except: pass
    for client in created_clients:
        wg_users[client["public_key"]] = {
            "name": client["name"],
            "group": group_name,
            "sub_token": client["sub_token"],
            "limit_gb": limit_gb,
            "expire_date": expire_date,
            "active": True,
            "duration_days": int(expire_days) if expire_days else None,
            "start_on_first_connect": start_on_first_connect,
            "config": client["config"]
        }
    with open('/www/wwwroot/mhpanel/wg_users.json', 'w') as f:
        json.dump(wg_users, f, indent=2)
        
    return jsonify({"success": True, "clients": created_clients})


def get_wg_traffic():
    traffic = {}
    try:
        res = subprocess.run(["wg", "show", "wg0", "dump"], capture_output=True, text=True, timeout=5)
        if res.returncode == 0:
            for line in res.stdout.strip().split("\n"):
                parts = line.split()
                if len(parts) >= 8:
                    pubkey = parts[0]
                    rx = int(parts[5])
                    tx = int(parts[6])
                    traffic[pubkey] = {"rx": rx, "tx": tx}
    except Exception:
        pass
    return traffic

@app.route("/api/wireguard/peers", methods=["GET"])
def api_wg_peers():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    peers = []
    if not os.path.exists("/etc/wireguard/wg0.conf"):
        return jsonify(peers)
        
    current_peer = {}
    last_comment = None
    with open("/etc/wireguard/wg0.conf", "r") as f:
        for line in f:
            line = line.strip()
            if line.startswith("#"):
                comment = line.replace("#", "").strip()
                if comment.lower().startswith("name:"):
                    comment = comment[5:].strip()
                last_comment = comment
            elif line.lower() == "[peer]":
                if current_peer:
                    peers.append(current_peer)
                current_peer = {"name": last_comment if last_comment else "Client"}
                last_comment = None
            elif "=" in line and current_peer:
                parts = line.split("=", 1)
                key = parts[0].strip().lower()
                val = parts[1].strip()
                if key == "publickey":
                    current_peer["public_key"] = val
                elif key == "allowedips":
                    current_peer["ip"] = val.replace("/32", "")
        if current_peer:
            peers.append(current_peer)
            
    wg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/wg_users.json'):
        with open('/www/wwwroot/mhpanel/wg_users.json', 'r') as f:
            try: wg_users = json.load(f)
            except: pass

    traffic = get_wg_traffic()
    wg_dirty = False
    now = datetime.now()
    
    for peer in peers:
        pubkey = peer.get("public_key")
        user_data = wg_users.get(pubkey, {})
        peer["limit_gb"] = user_data.get("limit_gb")
        peer["expire_date"] = user_data.get("expire_date")
        peer["active"] = user_data.get("active", True)
        peer["config"] = user_data.get("config", "")
        peer["duration_days"] = user_data.get("duration_days")
        peer["start_on_first_connect"] = user_data.get("start_on_first_connect", False)
        peer["group"] = user_data.get("group", "عمومی")
        
        # Ensure sub_token exists
        sub_tok = user_data.get("sub_token")
        if not sub_tok:
            sub_tok = secrets.token_urlsafe(16)
            user_data["sub_token"] = sub_tok
            wg_users[pubkey] = user_data
            wg_dirty = True
        peer["sub_token"] = sub_tok

        tdata = traffic.get(pubkey, {"rx": 0, "tx": 0})
        peer["rx"] = tdata["rx"]
        peer["tx"] = tdata["tx"]
        total_usage = tdata["rx"] + tdata["tx"]
        peer["total_usage"] = total_usage
        
        # Calculate status flags
        is_date_expired = False
        if peer.get("expire_date"):
            try:
                exp_dt = datetime.strptime(str(peer["expire_date"]).split()[0], "%Y-%m-%d")
                if exp_dt < now:
                    is_date_expired = True
            except Exception:
                pass

        is_traffic_expired = False
        if peer.get("limit_gb"):
            try:
                limit_bytes = float(peer["limit_gb"]) * (1024 ** 3)
                if total_usage >= limit_bytes:
                    is_traffic_expired = True
            except Exception:
                pass

        if not peer.get("active", True):
            st = "disabled"
        elif is_traffic_expired:
            st = "traffic_expired"
        elif is_date_expired:
            st = "date_expired"
        else:
            st = "active"

        peer["status"] = st
        peer["is_date_expired"] = is_date_expired
        peer["is_traffic_expired"] = is_traffic_expired

    if wg_dirty:
        try:
            with open('/www/wwwroot/mhpanel/wg_users.json', 'w') as f:
                json.dump(wg_users, f, indent=2)
        except Exception:
            pass

    return jsonify(peers)

@app.route("/api/wireguard/client/edit", methods=["POST"])
def api_wg_client_edit():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    pubkey = request.json.get("public_key")
    new_name = request.json.get("name", "").strip()
    new_name = re.sub(r'[^a-zA-Z0-9_\- ]', '', new_name)
    limit_gb = request.json.get("limit_gb")
    expire_days = request.json.get("expire_days")
    start_on_first_connect = request.json.get("start_on_first_connect")
    group_name = request.json.get("group")
    active_val = request.json.get("active")
    
    if not pubkey or not new_name:
        return jsonify({"success": False, "error": "Missing parameters"}), 400
        
    if not os.path.exists("/etc/wireguard/wg0.conf"):
        return jsonify({"success": False, "error": "WireGuard is not installed."}), 400
        
    try:
        with open("/etc/wireguard/wg0.conf", "r") as f:
            lines = f.readlines()
            
        updated = False
        for i, line in enumerate(lines):
            if "PublicKey" in line and pubkey in line:
                j = i
                while j >= 0:
                    if lines[j].strip().lower() == "[peer]":
                        if j - 1 >= 0 and lines[j-1].strip().startswith("#"):
                            lines[j-1] = f"# Name: {new_name}\n"
                            updated = True
                        break
                    j -= 1
                if updated:
                    break
                    
        if not updated:
            return jsonify({"success": False, "error": "Client name comment not found above [Peer]"}), 404
            
        with open("/etc/wireguard/wg0.conf", "w") as f:
            f.writelines(lines)
            
        subprocess.run(f"wg syncconf wg0 <(wg-quick strip wg0)", shell=True, executable="/bin/bash")
        
        wg_users = {}
        if os.path.exists('/www/wwwroot/mhpanel/wg_users.json'):
            with open('/www/wwwroot/mhpanel/wg_users.json', 'r') as f:
                try: wg_users = json.load(f)
                except: pass
                
        if pubkey in wg_users:
            wg_users[pubkey]["name"] = new_name
            if limit_gb is not None:
                wg_users[pubkey]["limit_gb"] = float(limit_gb) if str(limit_gb).strip() else None
                
            if expire_days is not None:
                days = int(expire_days) if str(expire_days).strip() else None
                wg_users[pubkey]["duration_days"] = days
                if days:
                    if not wg_users[pubkey].get("start_on_first_connect") and not start_on_first_connect:
                        wg_users[pubkey]["expire_date"] = (datetime.now() + timedelta(days=days)).strftime("%Y-%m-%d %H:%M:%S")
                else:
                    wg_users[pubkey]["expire_date"] = None
                    
            if start_on_first_connect is not None:
                wg_users[pubkey]["start_on_first_connect"] = bool(start_on_first_connect)
                if bool(start_on_first_connect):
                    wg_users[pubkey]["expire_date"] = None
                    wg_users[pubkey]["first_connect_time"] = None
                    
            if group_name is not None:
                wg_users[pubkey]["group"] = str(group_name).strip() or "عمومی"
                
            if active_val is not None:
                wg_users[pubkey]["active"] = bool(active_val)
                    
            with open('/www/wwwroot/mhpanel/wg_users.json', 'w') as f:
                json.dump(wg_users, f, indent=2)
                
        return jsonify({"success": True})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route("/api/wireguard/client", methods=["POST"])
def api_wg_client():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    name = request.json.get("name", "Client").strip()
    name = re.sub(r'[^a-zA-Z0-9_\-]', '', name)
    if not name:
        name = "Client"
        
    limit_gb = request.json.get("limit_gb")
    expire_days = request.json.get("expire_days")
    start_on_first_connect = request.json.get("start_on_first_connect", False)
    group_name = str(request.json.get("group", "عمومی")).strip() or "عمومی"
    
    expire_date = None
    if expire_days and not start_on_first_connect:
        from datetime import datetime, timedelta
        expire_date = (datetime.now() + timedelta(days=int(expire_days))).strftime("%Y-%m-%d")
        
    if not os.path.exists("/etc/wireguard/wg0.conf"):
        return jsonify({"success": False, "error": "WireGuard is not installed."}), 400
        
    privkey = subprocess.run(["wg", "genkey"], stdout=subprocess.PIPE, text=True).stdout.strip()
    pubkey = subprocess.run(["wg", "pubkey"], input=privkey, stdout=subprocess.PIPE, text=True).stdout.strip()
    
    with open("/etc/wireguard/wg0.conf", "r") as f:
        content = f.read()

    server_pubkey = ""
    if os.path.exists("/etc/wireguard/public.key"):
        with open("/etc/wireguard/public.key", "r") as f:
            server_pubkey = f.read().strip()
    if not server_pubkey and os.path.exists("/etc/wireguard/wg0.conf"):
        m = re.search(r"^PrivateKey\s*=\s*(.+)$", content, re.MULTILINE | re.IGNORECASE)
        if m:
            res_pk = subprocess.run(["wg", "pubkey"], input=m.group(1).strip(), capture_output=True, text=True)
            server_pubkey = res_pk.stdout.strip()
            if server_pubkey:
                with open("/etc/wireguard/public.key", "w") as f:
                    f.write(server_pubkey)
            
    port = get_active_port("wireguard") or 904
    
    # Parse client base IP prefix from wg0.conf or use wireguard_subnet setting
    settings = get_protocol_settings()
    wg_subnet = settings.get("wireguard_subnet", "10.13.0.0")
    subnet_prefix = wg_subnet.rsplit(".", 1)[0]
    
    match_addr = re.search(r"^Address\s*=\s*(\d+\.\d+\.\d+)\.\d+", content, re.MULTILINE | re.IGNORECASE)
    if match_addr:
        subnet_prefix = match_addr.group(1)
        
    escaped_prefix = subnet_prefix.replace(".", r"\.")
    used_ips = [int(ip) for ip in re.findall(escaped_prefix + r'\.(\d+)', content)]
    next_ip_num = 2
    while next_ip_num in used_ips:
        next_ip_num += 1
        if next_ip_num > 254:
            return jsonify({"success": False, "error": "IP pool exhausted"}), 400
            
    client_ip = f"{subnet_prefix}.{next_ip_num}"
    
    # Get server endpoint
    server_ip = settings.get("wireguard_server_ip", "").strip() or get_server_domain() or get_server_public_ip()
    if ":" in server_ip and not (server_ip.startswith("[") and server_ip.endswith("]")):
        server_ip = get_server_public_ip()
            
    with open("/etc/wireguard/wg0.conf", "a") as f:
        f.write(f"\n# Name: {name}\n[Peer]\nPublicKey = {pubkey}\nAllowedIPs = {client_ip}/32\n")
        
    subprocess.run(f"wg syncconf wg0 <(wg-quick strip wg0)", shell=True, executable="/bin/bash")
    
    # Get custom WireGuard DNS
    wg_dns1 = settings.get("wireguard_dns1", "8.8.8.8")
    wg_dns2 = settings.get("wireguard_dns2", "8.8.4.4")
    dns_val = f"{wg_dns1}, {wg_dns2}" if (wg_dns1 and wg_dns2) else (wg_dns1 or wg_dns2 or "8.8.8.8")
    
    client_config = f"""[Interface]
PrivateKey = {privkey}
Address = {client_ip}/32
DNS = {dns_val}

[Peer]
PublicKey = {server_pubkey}
Endpoint = {server_ip}:{port}
AllowedIPs = 0.0.0.0/0
PersistentKeepalive = 25
"""
    sub_token = secrets.token_urlsafe(16)

    wg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/wg_users.json'):
        with open('/www/wwwroot/mhpanel/wg_users.json', 'r') as f:
            try: wg_users = json.load(f)
            except: pass
    
    wg_users[pubkey] = {
        "name": name,
        "group": group_name,
        "sub_token": sub_token,
        "limit_gb": limit_gb,
        "expire_date": expire_date,
        "active": True,
        "duration_days": int(expire_days) if expire_days else None,
        "start_on_first_connect": start_on_first_connect,
        "config": client_config
    }
    
    with open('/www/wwwroot/mhpanel/wg_users.json', 'w') as f:
        json.dump(wg_users, f, indent=2)
    
    return jsonify({
        "success": True,
        "config": client_config,
        "name": name,
        "ip": client_ip,
        "group": group_name,
        "sub_token": sub_token
    })

@app.route("/api/wireguard/multiport", methods=["GET", "POST"])
def api_wg_multiport():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    if request.method == "POST":
        data = request.json or {}
        cfg = get_wg_multiport_config()
        if "enabled" in data:
            cfg["enabled"] = bool(data["enabled"])
        if "ports" in data and isinstance(data["ports"], list):
            valid_ports = []
            for p in data["ports"]:
                try:
                    p_int = int(p)
                    if 1 <= p_int <= 65535 and p_int not in valid_ports:
                        valid_ports.append(p_int)
                except Exception:
                    pass
            cfg["ports"] = valid_ports
        target = get_active_port("wireguard") or 51820
        cfg["target_port"] = target
        try:
            with open(WIREGUARD_MULTIPORT_FILE, "w") as f:
                json.dump(cfg, f, indent=2)
            apply_wg_multiport_iptables(cfg)
            return jsonify({"success": True, "config": cfg})
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500
    return jsonify(get_wg_multiport_config())

@app.route("/api/wireguard/client/multiport", methods=["GET"])
def api_wg_client_multiport():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    pubkey = request.args.get("public_key")
    if not pubkey:
        return jsonify({"error": "Missing public_key"}), 400
    wg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/wg_users.json'):
        try:
            with open('/www/wwwroot/mhpanel/wg_users.json', 'r') as f:
                wg_users = json.load(f)
        except: pass
    user_data = wg_users.get(pubkey, {})
    base_cfg = user_data.get("config", "")
    if not base_cfg:
        return jsonify({"error": "Config not found"}), 404
    domain = get_server_domain() or get_server_public_ip()
    mp_cfg = get_wg_multiport_config()
    ports = list(mp_cfg.get("ports", []))
    target = mp_cfg.get("target_port") or 51820
    if target not in ports:
        ports.insert(0, target)
    port_configs = []
    for p in ports:
        cfg_p = re.sub(r"(Endpoint\s*=\s*[^:\s]+):\d+", rf"\\1:{p}", base_cfg)
        port_configs.append({"port": p, "endpoint": f"{domain}:{p}", "config": cfg_p})
    return jsonify({
        "success": True,
        "ports": ports,
        "configs": port_configs,
        "sub_token": user_data.get("sub_token", ""),
        "name": user_data.get("name", "Client")
    })


@app.route("/api/wireguard/client/delete", methods=["POST"])
def api_wg_client_delete():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    pubkey = request.json.get("public_key")
    if not pubkey:
        return jsonify({"success": False, "error": "Missing public key"}), 400
        
    if not os.path.exists("/etc/wireguard/wg0.conf"):
        return jsonify({"success": False, "error": "WireGuard is not installed."}), 400
        
    with open("/etc/wireguard/wg0.conf", "r") as f:
        lines = f.readlines()
        
    new_lines = []
    skip_lines = 0
    
    for i, line in enumerate(lines):
        if skip_lines > 0:
            skip_lines -= 1
            continue
        if "[Peer]" in line:
            block_lines = []
            j = i
            while j < len(lines) and not lines[j].strip().startswith("[Interface]") and not (lines[j].strip().startswith("[Peer]") and j > i):
                block_lines.append(lines[j])
                j += 1
            block_content = "".join(block_lines)
            if pubkey in block_content:
                if len(new_lines) > 0 and new_lines[-1].strip().startswith("# Name:"):
                    new_lines.pop()
                skip_lines = len(block_lines) - 1
                continue
        new_lines.append(line)
        
    with open("/etc/wireguard/wg0.conf", "w") as f:
        f.writelines(new_lines)
        
    subprocess.run(f"wg syncconf wg0 <(wg-quick strip wg0)", shell=True, executable="/bin/bash")
    
    if os.path.exists('/www/wwwroot/mhpanel/wg_users.json'):
        wg_users = {}
        with open('/www/wwwroot/mhpanel/wg_users.json', 'r') as f:
            try: wg_users = json.load(f)
            except: pass
        if pubkey in wg_users:
            del wg_users[pubkey]
            with open('/www/wwwroot/mhpanel/wg_users.json', 'w') as f:
                json.dump(wg_users, f)
                
    return jsonify({"success": True})

# --- MTProto Multi-Instance API ---
@app.route("/api/amneziawg/client/bulk", methods=["POST"])
def api_awg_client_bulk():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    prefix = request.json.get("prefix", "Client").strip()
    prefix = re.sub(r'[^a-zA-Z0-9_\-]', '', prefix)
    count = request.json.get("count", 1)
    limit_gb = request.json.get("limit_gb")
    expire_days = request.json.get("expire_days")
    start_on_first_connect = request.json.get("start_on_first_connect", False)
    group_name = str(request.json.get("group", "عمومی")).strip() or "عمومی"
    
    expire_date = None
    if expire_days and not start_on_first_connect:
        from datetime import datetime, timedelta
        expire_date = (datetime.now() + timedelta(days=int(expire_days))).strftime("%Y-%m-%d")
    try:
        count = int(count)
    except (ValueError, TypeError):
        count = 1
        
    if count < 1 or count > 50:
        return jsonify({"success": False, "error": "Count must be between 1 and 50"}), 400
        
    if not os.path.exists("/etc/amnezia/amneziawg/awg0.conf"):
        return jsonify({"success": False, "error": "WireGuard is not installed."}), 400
        
    settings = get_protocol_settings()
    wg_subnet = settings.get("amneziawg_subnet", "10.13.0.0")
    subnet_prefix = wg_subnet.rsplit(".", 1)[0]
    
    with open("/etc/amnezia/amneziawg/awg0.conf", "r") as f:
        content = f.read()
        
    match_addr = re.search(r"^Address\s*=\s*(\d+\.\d+\.\d+)\.\d+", content, re.MULTILINE | re.IGNORECASE)
    if match_addr:
        subnet_prefix = match_addr.group(1)
        
    server_pubkey = ""
    if os.path.exists("/etc/amnezia/amneziawg/public.key"):
        with open("/etc/amnezia/amneziawg/public.key", "r") as f:
            server_pubkey = f.read().strip()
    if not server_pubkey and os.path.exists("/etc/amnezia/amneziawg/awg0.conf"):
        m = re.search(r"^PrivateKey\s*=\s*(.+)$", content, re.MULTILINE | re.IGNORECASE)
        if m:
            res_pk = subprocess.run(["awg", "pubkey"], input=m.group(1).strip(), capture_output=True, text=True)
            server_pubkey = res_pk.stdout.strip()
            if server_pubkey:
                with open("/etc/amnezia/amneziawg/public.key", "w") as f:
                    f.write(server_pubkey)
            
    port = get_active_port("amneziawg") or 51820
    
    server_ip = settings.get("amneziawg_server_ip", "").strip() or get_server_domain() or get_server_public_ip()
    if ":" in server_ip and not (server_ip.startswith("[") and server_ip.endswith("]")):
        server_ip = get_server_public_ip()
            
    wg_dns1 = settings.get("amneziawg_dns1", "8.8.8.8")
    wg_dns2 = settings.get("amneziawg_dns2", "8.8.4.4")
    dns_val = f"{wg_dns1}, {wg_dns2}" if (wg_dns1 and wg_dns2) else (wg_dns1 or wg_dns2 or "8.8.8.8")

    # Extract obfuscation parameters from awg0.conf
    obf_params = ""
    for param in ["Jc", "Jmin", "Jmax", "S1", "S2", "S3", "S4", "H1", "H2", "H3", "H4"]:
        match = re.search(fr"^{param}\s*=\s*(.+)$", content, re.MULTILINE | re.IGNORECASE)
        if match:
            obf_params += f"{param} = {match.group(1).strip()}\n"
    
    escaped_prefix = subnet_prefix.replace(".", r"\.")
    used_ips = [int(ip) for ip in re.findall(escaped_prefix + r'\.(\d+)', content)]
    
    created_clients = []
    awg0_append_text = ""
    current_next_ip = 2
    
    for idx in range(1, count + 1):
        name = f"{prefix}-{idx}"
        while current_next_ip in used_ips:
            current_next_ip += 1
        if current_next_ip > 254:
            break
            
        client_ip = f"{subnet_prefix}.{current_next_ip}"
        used_ips.append(current_next_ip)
        
        privkey = subprocess.run(["awg", "genkey"], stdout=subprocess.PIPE, text=True).stdout.strip()
        pubkey = subprocess.run(["awg", "pubkey"], input=privkey, stdout=subprocess.PIPE, text=True).stdout.strip()
        
        awg0_append_text += f"\n# Name: {name}\n[Peer]\nPublicKey = {pubkey}\nAllowedIPs = {client_ip}/32\n"
        
        client_config = f"""[Interface]
PrivateKey = {privkey}
Address = {client_ip}/32
DNS = {dns_val}
MTU = 1280
{obf_params}
[Peer]
PublicKey = {server_pubkey}
Endpoint = {server_ip}:{port}
AllowedIPs = 0.0.0.0/0
PersistentKeepalive = 25
"""
        sub_token = secrets.token_urlsafe(16)
        created_clients.append({
            "name": name,
            "ip": client_ip,
            "public_key": pubkey,
            "config": client_config,
            "group": group_name,
            "sub_token": sub_token
        })
        
    if awg0_append_text:
        with open("/etc/amnezia/amneziawg/awg0.conf", "a") as f:
            f.write(awg0_append_text)
        subprocess.run(f"awg syncconf awg0 <(awg-quick strip awg0)", shell=True, executable="/bin/bash")
        
    awg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/awg_users.json'):
        with open('/www/wwwroot/mhpanel/awg_users.json', 'r') as f:
            try: awg_users = json.load(f)
            except: pass
    for client in created_clients:
        awg_users[client["public_key"]] = {
            "name": client["name"],
            "group": group_name,
            "sub_token": client["sub_token"],
            "limit_gb": limit_gb,
            "expire_date": expire_date,
            "active": True,
            "duration_days": int(expire_days) if expire_days else None,
            "start_on_first_connect": start_on_first_connect,
            "config": client["config"]
        }
    with open('/www/wwwroot/mhpanel/awg_users.json', 'w') as f:
        json.dump(awg_users, f, indent=2)
        
    return jsonify({"success": True, "clients": created_clients})


def get_awg_traffic():
    traffic = {}
    try:
        res = subprocess.run(["awg", "show", "awg0", "dump"], capture_output=True, text=True, timeout=5)
        if res.returncode == 0:
            for line in res.stdout.strip().split("\n"):
                parts = line.split()
                if len(parts) >= 8:
                    pubkey = parts[0]
                    rx = int(parts[5])
                    tx = int(parts[6])
                    traffic[pubkey] = {"rx": rx, "tx": tx}
    except Exception:
        pass
    return traffic

@app.route("/api/amneziawg/peers", methods=["GET"])
def api_awg_peers():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    peers = []
    if not os.path.exists("/etc/amnezia/amneziawg/awg0.conf"):
        return jsonify(peers)
        
    current_peer = {}
    last_comment = None
    with open("/etc/amnezia/amneziawg/awg0.conf", "r") as f:
        for line in f:
            line = line.strip()
            if line.startswith("#"):
                comment = line.replace("#", "").strip()
                if comment.lower().startswith("name:"):
                    comment = comment[5:].strip()
                last_comment = comment
            elif line.lower() == "[peer]":
                if current_peer:
                    peers.append(current_peer)
                current_peer = {"name": last_comment if last_comment else "Client"}
                last_comment = None
            elif "=" in line and current_peer:
                parts = line.split("=", 1)
                key = parts[0].strip().lower()
                val = parts[1].strip()
                if key == "publickey":
                    current_peer["public_key"] = val
                elif key == "allowedips":
                    current_peer["ip"] = val.replace("/32", "")
        if current_peer:
            peers.append(current_peer)
            
    awg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/awg_users.json'):
        with open('/www/wwwroot/mhpanel/awg_users.json', 'r') as f:
            try: awg_users = json.load(f)
            except: pass

    traffic = get_awg_traffic()
    active_awg_port = get_active_port("amneziawg") or 51820
    awg_users_dirty = False
    now = datetime.now()

    for peer in peers:
        pubkey = peer.get("public_key")
        user_data = awg_users.get(pubkey, {})
        peer["limit_gb"] = user_data.get("limit_gb")
        peer["expire_date"] = user_data.get("expire_date")
        peer["active"] = user_data.get("active", True)
        peer["group"] = user_data.get("group", "عمومی")
        
        # Ensure sub_token exists
        sub_tok = user_data.get("sub_token")
        if not sub_tok:
            sub_tok = secrets.token_urlsafe(16)
            user_data["sub_token"] = sub_tok
            awg_users[pubkey] = user_data
            awg_users_dirty = True
        peer["sub_token"] = sub_tok
        
        cfg = user_data.get("config", "")
        if cfg and f":{active_awg_port}" not in cfg:
            cfg = re.sub(r"(Endpoint\s*=\s*[^:\s]+):\d+", rf"\1:{active_awg_port}", cfg)
            user_data["config"] = cfg
            awg_users_dirty = True
        peer["config"] = cfg
        peer["duration_days"] = user_data.get("duration_days")
        peer["start_on_first_connect"] = user_data.get("start_on_first_connect", False)

        tdata = traffic.get(pubkey, {"rx": 0, "tx": 0})
        peer["rx"] = tdata["rx"]
        peer["tx"] = tdata["tx"]
        total_usage = tdata["rx"] + tdata["tx"]
        peer["total_usage"] = total_usage
        
        # Status calculation
        is_date_expired = False
        if peer.get("expire_date"):
            try:
                exp_dt = datetime.strptime(str(peer["expire_date"]).split()[0], "%Y-%m-%d")
                if exp_dt < now:
                    is_date_expired = True
            except Exception:
                pass

        is_traffic_expired = False
        if peer.get("limit_gb"):
            try:
                limit_bytes = float(peer["limit_gb"]) * (1024 ** 3)
                if total_usage >= limit_bytes:
                    is_traffic_expired = True
            except Exception:
                pass

        if not peer.get("active", True):
            st = "disabled"
        elif is_traffic_expired:
            st = "traffic_expired"
        elif is_date_expired:
            st = "date_expired"
        else:
            st = "active"

        peer["status"] = st
        peer["is_date_expired"] = is_date_expired
        peer["is_traffic_expired"] = is_traffic_expired
        
    if awg_users_dirty:
        try:
            with open('/www/wwwroot/mhpanel/awg_users.json', 'w') as f:
                json.dump(awg_users, f, indent=2)
        except Exception:
            pass
        
    return jsonify(peers)

@app.route("/api/amneziawg/client/edit", methods=["POST"])
def api_awg_client_edit():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    pubkey = request.json.get("public_key")
    new_name = request.json.get("name", "").strip()
    new_name = re.sub(r'[^a-zA-Z0-9_\- ]', '', new_name)
    limit_gb = request.json.get("limit_gb")
    expire_days = request.json.get("expire_days")
    start_on_first_connect = request.json.get("start_on_first_connect")
    group_name = request.json.get("group")
    active_val = request.json.get("active")
    
    if not pubkey or not new_name:
        return jsonify({"success": False, "error": "Missing parameters"}), 400
        
    if not os.path.exists("/etc/amnezia/amneziawg/awg0.conf"):
        return jsonify({"success": False, "error": "WireGuard is not installed."}), 400
        
    try:
        with open("/etc/amnezia/amneziawg/awg0.conf", "r") as f:
            lines = f.readlines()
            
        updated = False
        for i, line in enumerate(lines):
            if "PublicKey" in line and pubkey in line:
                j = i
                while j >= 0:
                    if lines[j].strip().lower() == "[peer]":
                        if j - 1 >= 0 and lines[j-1].strip().startswith("#"):
                            lines[j-1] = f"# Name: {new_name}\n"
                            updated = True
                        break
                    j -= 1
                if updated:
                    break
                    
        if not updated:
            return jsonify({"success": False, "error": "Client name comment not found above [Peer]"}), 404
            
        with open("/etc/amnezia/amneziawg/awg0.conf", "w") as f:
            f.writelines(lines)
            
        subprocess.run(f"awg syncconf awg0 <(awg-quick strip awg0)", shell=True, executable="/bin/bash")
        
        awg_users = {}
        if os.path.exists('/www/wwwroot/mhpanel/awg_users.json'):
            with open('/www/wwwroot/mhpanel/awg_users.json', 'r') as f:
                try: awg_users = json.load(f)
                except: pass
                
        if pubkey in awg_users:
            awg_users[pubkey]["name"] = new_name
            if limit_gb is not None:
                awg_users[pubkey]["limit_gb"] = float(limit_gb) if str(limit_gb).strip() else None
                
            if expire_days is not None:
                days = int(expire_days) if str(expire_days).strip() else None
                awg_users[pubkey]["duration_days"] = days
                if days:
                    if not awg_users[pubkey].get("start_on_first_connect") and not start_on_first_connect:
                        awg_users[pubkey]["expire_date"] = (datetime.now() + timedelta(days=days)).strftime("%Y-%m-%d %H:%M:%S")
                else:
                    awg_users[pubkey]["expire_date"] = None
                    
            if start_on_first_connect is not None:
                awg_users[pubkey]["start_on_first_connect"] = bool(start_on_first_connect)
                if bool(start_on_first_connect):
                    awg_users[pubkey]["expire_date"] = None
                    awg_users[pubkey]["first_connect_time"] = None
                    
            if group_name is not None:
                awg_users[pubkey]["group"] = str(group_name).strip() or "عمومی"

            if active_val is not None:
                awg_users[pubkey]["active"] = bool(active_val)
                    
            with open('/www/wwwroot/mhpanel/awg_users.json', 'w') as f:
                json.dump(awg_users, f, indent=2)
                
        return jsonify({"success": True})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route("/api/amneziawg/client", methods=["POST"])
def api_awg_client():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    name = request.json.get("name", "Client").strip()
    name = re.sub(r'[^a-zA-Z0-9_\-]', '', name)
    if not name:
        name = "Client"
        
    limit_gb = request.json.get("limit_gb")
    expire_days = request.json.get("expire_days")
    start_on_first_connect = request.json.get("start_on_first_connect", False)
    group_name = str(request.json.get("group", "عمومی")).strip() or "عمومی"
    
    expire_date = None
    if expire_days and not start_on_first_connect:
        from datetime import datetime, timedelta
        expire_date = (datetime.now() + timedelta(days=int(expire_days))).strftime("%Y-%m-%d")
        
    if not os.path.exists("/etc/amnezia/amneziawg/awg0.conf"):
        return jsonify({"success": False, "error": "WireGuard is not installed."}), 400
        
    privkey = subprocess.run(["awg", "genkey"], stdout=subprocess.PIPE, text=True).stdout.strip()
    pubkey = subprocess.run(["awg", "pubkey"], input=privkey, stdout=subprocess.PIPE, text=True).stdout.strip()
    
    server_pubkey = ""
    if os.path.exists("/etc/amnezia/amneziawg/awg0.conf"):
        with open("/etc/amnezia/amneziawg/awg0.conf", "r") as f:
            content = f.read()
            match_priv = re.search(r"^PrivateKey\s*=\s*(.+)$", content, re.MULTILINE | re.IGNORECASE)
            if match_priv:
                server_privkey = match_priv.group(1).strip()
                server_pubkey = subprocess.run(["awg", "pubkey"], input=server_privkey, stdout=subprocess.PIPE, text=True).stdout.strip()
            
    port = get_active_port("amneziawg") or 51820
    with open("/etc/amnezia/amneziawg/awg0.conf", "r") as f:
        content = f.read()
    
    # Parse client base IP prefix from awg0.conf or use amneziawg_subnet setting
    settings = get_protocol_settings()
    wg_subnet = settings.get("amneziawg_subnet", "10.13.0.0")
    subnet_prefix = wg_subnet.rsplit(".", 1)[0]
    
    match_addr = re.search(r"^Address\s*=\s*(\d+\.\d+\.\d+)\.\d+", content, re.MULTILINE | re.IGNORECASE)
    if match_addr:
        subnet_prefix = match_addr.group(1)
        
    escaped_prefix = subnet_prefix.replace(".", r"\.")
    used_ips = [int(ip) for ip in re.findall(escaped_prefix + r'\.(\d+)', content)]
    next_ip_num = 2
    while next_ip_num in used_ips:
        next_ip_num += 1
        if next_ip_num > 254:
            return jsonify({"success": False, "error": "IP pool exhausted"}), 400
            
    client_ip = f"{subnet_prefix}.{next_ip_num}"
    
    # Get server endpoint
    server_ip = settings.get("amneziawg_server_ip", "").strip() or get_server_domain() or get_server_public_ip()
    if ":" in server_ip and not (server_ip.startswith("[") and server_ip.endswith("]")):
        server_ip = get_server_public_ip()
            
    with open("/etc/amnezia/amneziawg/awg0.conf", "a") as f:
        f.write(f"\n# Name: {name}\n[Peer]\nPublicKey = {pubkey}\nAllowedIPs = {client_ip}/32\n")
        
    subprocess.run(f"awg syncconf awg0 <(awg-quick strip awg0)", shell=True, executable="/bin/bash")
    
    # Get custom WireGuard DNS
    wg_dns1 = settings.get("amneziawg_dns1", "8.8.8.8")
    wg_dns2 = settings.get("amneziawg_dns2", "8.8.4.4")
    dns_val = f"{wg_dns1}, {wg_dns2}" if (wg_dns1 and wg_dns2) else (wg_dns1 or wg_dns2 or "8.8.8.8")
    # Extract obfuscation parameters from awg0.conf
    obf_params = ""
    for param in ["Jc", "Jmin", "Jmax", "S1", "S2", "S3", "S4", "H1", "H2", "H3", "H4"]:
        match = re.search(fr"^{param}\s*=\s*(.+)$", content, re.MULTILINE | re.IGNORECASE)
        if match:
            obf_params += f"{param} = {match.group(1).strip()}\n"

    client_config = f"""[Interface]
PrivateKey = {privkey}
Address = {client_ip}/32
DNS = {dns_val}
MTU = 1280
{obf_params}
[Peer]
PublicKey = {server_pubkey}
Endpoint = {server_ip}:{port}
AllowedIPs = 0.0.0.0/0
PersistentKeepalive = 25
"""
    sub_token = secrets.token_urlsafe(16)

    awg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/awg_users.json'):
        with open('/www/wwwroot/mhpanel/awg_users.json', 'r') as f:
            try: awg_users = json.load(f)
            except: pass
    
    awg_users[pubkey] = {
        "name": name,
        "group": group_name,
        "sub_token": sub_token,
        "limit_gb": limit_gb,
        "expire_date": expire_date,
        "active": True,
        "duration_days": int(expire_days) if expire_days else None,
        "start_on_first_connect": start_on_first_connect,
        "config": client_config
    }
    
    with open('/www/wwwroot/mhpanel/awg_users.json', 'w') as f:
        json.dump(awg_users, f, indent=2)
    
    return jsonify({
        "success": True,
        "config": client_config,
        "name": name,
        "ip": client_ip,
        "group": group_name,
        "sub_token": sub_token
    })

@app.route("/api/amneziawg/multiport", methods=["GET", "POST"])
def api_awg_multiport():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    if request.method == "POST":
        data = request.json or {}
        cfg = get_awg_multiport_config()
        if "enabled" in data:
            cfg["enabled"] = bool(data["enabled"])
        if "ports" in data and isinstance(data["ports"], list):
            valid_ports = []
            for p in data["ports"]:
                try:
                    p_int = int(p)
                    if 1 <= p_int <= 65535 and p_int not in valid_ports:
                        valid_ports.append(p_int)
                except Exception:
                    pass
            cfg["ports"] = valid_ports
        target = get_active_port("amneziawg") or 443
        cfg["target_port"] = target
        try:
            with open(AMNEZIAWG_MULTIPORT_FILE, "w") as f:
                json.dump(cfg, f, indent=2)
            apply_awg_multiport_iptables(cfg)
            return jsonify({"success": True, "config": cfg})
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500
    return jsonify(get_awg_multiport_config())

@app.route("/api/amneziawg/client/multiport", methods=["GET"])
def api_awg_client_multiport():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    pubkey = request.args.get("public_key")
    if not pubkey:
        return jsonify({"error": "Missing public_key"}), 400
    awg_users = {}
    if os.path.exists('/www/wwwroot/mhpanel/awg_users.json'):
        try:
            with open('/www/wwwroot/mhpanel/awg_users.json', 'r') as f:
                awg_users = json.load(f)
        except: pass
    user_data = awg_users.get(pubkey, {})
    base_cfg = user_data.get("config", "")
    if not base_cfg:
        return jsonify({"error": "Config not found"}), 404
    domain = get_server_domain() or get_server_public_ip()
    mp_cfg = get_awg_multiport_config()
    ports = list(mp_cfg.get("ports", []))
    target = mp_cfg.get("target_port") or 443
    if target not in ports:
        ports.insert(0, target)
    port_configs = []
    for p in ports:
        cfg_p = re.sub(r"(Endpoint\s*=\s*[^:\s]+):\d+", rf"\1:{p}", base_cfg)
        port_configs.append({"port": p, "endpoint": f"{domain}:{p}", "config": cfg_p})
    return jsonify({
        "success": True,
        "ports": ports,
        "configs": port_configs,
        "sub_token": user_data.get("sub_token", ""),
        "name": user_data.get("name", "Client")
    })

@app.route("/api/amneziawg/preset", methods=["POST"])
def api_awg_apply_preset():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    data = request.json or {}
    preset_name = data.get("preset", "").strip()
    
    conf_path = "/etc/amnezia/amneziawg/awg0.conf"
    if not os.path.exists(conf_path):
        return jsonify({"success": False, "error": "AmneziaWG is not installed."}), 400
        
    import random
    
    # Generate 4 high-entropy random headers
    h1 = random.randint(100000000, 2000000000)
    h2 = random.randint(100000000, 2000000000)
    h3 = random.randint(100000000, 2000000000)
    h4 = random.randint(100000000, 2000000000)
    
    params = {}
    ver = "v3"
    desc = ""
    
    if preset_name == "mci_irancell":
        # Irancell & MCI Mobile Aggressive DPI Bypass
        params = {
            "Jc": 5, "Jmin": 50, "Jmax": 100,
            "S1": 64, "S2": 48, "S3": 56, "S4": 56,
            "H1": h1, "H2": h2, "H3": h3, "H4": h4
        }
        ver = "v3"
        desc = "پیکربندی تهاجمی همراه اول و ایرانسل با پکت‌های فیک و پدینگ لایه انتقال"
    elif preset_name == "adsl_fixed":
        # Fixed Broadband / ADSL / VDSL Balanced
        params = {
            "Jc": 3, "Jmin": 30, "Jmax": 60,
            "S1": 32, "S2": 32, "S3": 0, "S4": 0,
            "H1": h1, "H2": h2, "H3": h3, "H4": h4
        }
        ver = "v2"
        desc = "پیکربندی متوازن و پایدار اینترنت خانگی (مخابرات، شاتل، آسیاتک، های‌وب)"
    elif preset_name == "extreme_dpi":
        # Deep Neural DPI & Statistical Analysis Extreme Camouflage
        params = {
            "Jc": 8, "Jmin": 64, "Jmax": 140,
            "S1": 96, "S2": 72, "S3": 80, "S4": 80,
            "H1": h1, "H2": h2, "H3": h3, "H4": h4
        }
        ver = "v3"
        desc = "استتار حداکثری هدرها و ترافیک جهت خنثی‌سازی هوش مصنوعی و DPI عمیق اپراتورها"
    elif preset_name == "randomize":
        # Fresh unique random keys
        params = {
            "Jc": random.randint(4, 7),
            "Jmin": random.randint(40, 60),
            "Jmax": random.randint(80, 130),
            "S1": random.randint(32, 96),
            "S2": random.randint(32, 80),
            "S3": random.randint(40, 80),
            "S4": random.randint(40, 80),
            "H1": h1, "H2": h2, "H3": h3, "H4": h4
        }
        ver = "v3"
        desc = "تولید هدرهای تصادفی و منحصر‌به‌فرد تازه برای سرور"
    else:
        return jsonify({"success": False, "error": f"Unknown preset: {preset_name}"}), 400
        
    try:
        with open(conf_path, "r") as f:
            lines = f.readlines()
            
        new_lines = []
        found_keys = set()
        version_replaced = False
        
        for line in lines:
            line_str = line.strip()
            if line_str.startswith("#") and "version" in line_str.lower():
                new_lines.append(f"# Version = {ver}\n")
                version_replaced = True
                continue
            m = re.match(r'^(Jc|Jmin|Jmax|S1|S2|S3|S4|H1|H2|H3|H4)\s*=\s*(.*)', line_str, re.IGNORECASE)
            if m:
                k = m.group(1)
                # Normalize key
                for pk in params:
                    if pk.lower() == k.lower():
                        new_lines.append(f"{pk} = {params[pk]}\n")
                        found_keys.add(pk)
                        break
                continue
            new_lines.append(line)
            
        # Add any missing keys inside [Interface]
        for pk, val in params.items():
            if pk not in found_keys:
                # Find [Interface] and insert
                for idx, nl in enumerate(new_lines):
                    if nl.strip().lower() == "[interface]":
                        new_lines.insert(idx + 1, f"{pk} = {val}\n")
                        break
                        
        if not version_replaced:
            for idx, nl in enumerate(new_lines):
                if nl.strip().lower() == "[interface]":
                    new_lines.insert(idx + 1, f"# Version = {ver}\n")
                    break

        with open(conf_path, "w") as f:
            f.writelines(new_lines)
            
        # Synchronize client configurations in awg_users.json
        if os.path.exists("/www/wwwroot/mhpanel/awg_users.json"):
            try:
                with open("/www/wwwroot/mhpanel/awg_users.json", "r") as f:
                    u_data = json.load(f)
                for pk, u in u_data.items():
                    cfg = u.get("config", "")
                    if cfg:
                        for param_k, param_v in params.items():
                            if re.search(fr"^{param_k}\s*=.*$", cfg, re.MULTILINE | re.IGNORECASE):
                                cfg = re.sub(fr"^{param_k}\s*=.*$", f"{param_k} = {param_v}", cfg, flags=re.MULTILINE | re.IGNORECASE)
                            else:
                                cfg = re.sub(r"(\[Interface\][\s\S]*?MTU\s*=\s*\d+)", rf"\1\n{param_k} = {param_v}", cfg, count=1)
                        if ver == "v2":
                            cfg = re.sub(r"^S3\s*=.*$\n?", "", cfg, flags=re.MULTILINE | re.IGNORECASE)
                            cfg = re.sub(r"^S4\s*=.*$\n?", "", cfg, flags=re.MULTILINE | re.IGNORECASE)
                        u["config"] = cfg
                with open("/www/wwwroot/mhpanel/awg_users.json", "w") as f:
                    json.dump(u_data, f, indent=2)
            except Exception as e:
                print(f"Error syncing client configs with preset: {e}")

        subprocess.run(["systemctl", "restart", "awg-quick@awg0"], check=False)
        return jsonify({
            "success": True,
            "preset": preset_name,
            "version": ver,
            "description": desc,
            "params": params
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/amneziawg/client/delete", methods=["POST"])
def api_awg_client_delete():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    pubkey = request.json.get("public_key")
    if not pubkey:
        return jsonify({"success": False, "error": "Missing public key"}), 400
        
    if not os.path.exists("/etc/amnezia/amneziawg/awg0.conf"):
        return jsonify({"success": False, "error": "AmneziaWG is not installed."}), 400
        
    with open("/etc/amnezia/amneziawg/awg0.conf", "r") as f:
        lines = f.readlines()
        
    new_lines = []
    skip_lines = 0
    
    for i, line in enumerate(lines):
        if skip_lines > 0:
            skip_lines -= 1
            continue
        if "[Peer]" in line:
            block_lines = []
            j = i
            while j < len(lines) and not lines[j].strip().startswith("[Interface]") and not (lines[j].strip().startswith("[Peer]") and j > i):
                block_lines.append(lines[j])
                j += 1
            block_content = "".join(block_lines)
            if pubkey in block_content:
                if len(new_lines) > 0 and new_lines[-1].strip().startswith("# Name:"):
                    new_lines.pop()
                skip_lines = len(block_lines) - 1
                continue
        new_lines.append(line)
        
    with open("/etc/amnezia/amneziawg/awg0.conf", "w") as f:
        f.writelines(new_lines)
        
    subprocess.run(f"awg syncconf awg0 <(awg-quick strip awg0)", shell=True, executable="/bin/bash")
    
    if os.path.exists('/www/wwwroot/mhpanel/awg_users.json'):
        awg_users = {}
        with open('/www/wwwroot/mhpanel/awg_users.json', 'r') as f:
            try: awg_users = json.load(f)
            except: pass
        if pubkey in awg_users:
            del awg_users[pubkey]
            with open('/www/wwwroot/mhpanel/awg_users.json', 'w') as f:
                json.dump(awg_users, f)
                
    return jsonify({"success": True})

