@app.route("/api/openvpn/ca/regenerate", methods=["POST"])
def api_openvpn_ca_regenerate():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
        
    try:
        os.makedirs("/etc/vpn-ca", exist_ok=True)
        os.makedirs("/etc/openvpn", exist_ok=True)
        subprocess.run("openssl genrsa -out /etc/vpn-ca/ca.key 2048", shell=True, check=True)
        subprocess.run("openssl req -x509 -new -nodes -key /etc/vpn-ca/ca.key -subj '/CN=MHPanel Root CA' -days 3650 -out /etc/vpn-ca/ca.crt", shell=True, check=True)
        subprocess.run("openssl genrsa -out /etc/vpn-ca/vpn-server.key 2048", shell=True, check=True)
        subprocess.run("openssl req -new -key /etc/vpn-ca/vpn-server.key -subj '/CN=vpn-server' -out /etc/vpn-ca/vpn-server.csr", shell=True, check=True)
        subprocess.run("openssl x509 -req -in /etc/vpn-ca/vpn-server.csr -CA /etc/vpn-ca/ca.crt -CAkey /etc/vpn-ca/ca.key -CAcreateserial -out /etc/vpn-ca/vpn-server.crt -days 3650", shell=True, check=True)
        subprocess.run("openvpn --genkey --secret /etc/openvpn/tls-crypt.key", shell=True, check=True)
        subprocess.run("ln -sf /etc/vpn-ca/ca.crt /etc/openvpn/ca.crt", shell=True)
        subprocess.run("ln -sf /etc/openvpn/tls-crypt.key /etc/openvpn/tc.key", shell=True)
        subprocess.run(["systemctl", "restart", "openvpn-server@server", "openvpn-server@server-tcp", "openvpn@server", "ocserv"], check=False)
        return jsonify({"success": True, "message": "گواهی و کلیدهای OpenVPN با موفقیت مجدداً تولید و سرویس‌ها راه‌اندازی شدند."})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route("/api/system/ports", methods=["GET"])
def api_system_ports():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    
    ports = []
    try:
        res = subprocess.run(["ss", "-tulnp"], capture_output=True, text=True, timeout=5)
        if res.returncode == 0:
            lines = res.stdout.strip().split("\n")
            for line in lines[1:]:
                parts = line.split()
                if len(parts) < 5:
                    continue
                netid = parts[0]
                local_addr_port = parts[4]
                
                if "]" in local_addr_port:
                    addr_part, port_part = local_addr_port.rsplit(":", 1)
                else:
                    addr_part, port_part = local_addr_port.rsplit(":", 1)
                
                try:
                    port = int(port_part)
                except ValueError:
                    port = port_part

                process_info = "-"
                pid = "-"
                if len(parts) >= 7:
                    proc_col = parts[6]
                    match = re.search(r'users:\(\("([^"]+)",pid=(\d+)', proc_col)
                    if match:
                        process_info = match.group(1)
                        pid = match.group(2)
                    else:
                        match2 = re.search(r'pid=(\d+)', proc_col)
                        if match2:
                            pid = match2.group(1)
                        match3 = re.search(r'\(\(([^,]+)', proc_col)
                        if match3:
                            process_info = match3.group(1).replace('"', '')
                
                ports.append({
                    "protocol": netid,
                    "address": addr_part,
                    "port": port,
                    "process": process_info,
                    "pid": pid
                })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500
        
    return jsonify(ports)

# --- Cloudflare WARP & TCP BBR Management ---

def get_warp_info():
    import shutil
    cli = shutil.which("warp-cli")
    if not cli:
        return {"installed": False, "connected": False, "status": "Not Installed", "account_type": "-", "license": "", "socks_port": 40000}
    info = {"installed": True, "connected": False, "status": "Disconnected", "account_type": "Free", "license": "", "socks_port": 40000}
    try:
        res = subprocess.run(["warp-cli", "--accept-tos", "status"], capture_output=True, text=True, timeout=5)
        out = res.stdout
        if "Connected" in out:
            info["connected"] = True
            info["status"] = "Connected"
        elif "Connecting" in out:
            info["status"] = "Connecting"
        else:
            info["status"] = "Disconnected"

        res_reg = subprocess.run(["warp-cli", "--accept-tos", "registration", "show"], capture_output=True, text=True, timeout=5)
        out_reg = res_reg.stdout
        for line in out_reg.splitlines():
            line = line.strip()
            if "Account type:" in line:
                info["account_type"] = line.split(":", 1)[1].strip()
            elif "License:" in line:
                info["license"] = line.split(":", 1)[1].strip()
    except Exception as e:
        info["error"] = str(e)
    return info

