def get_installed_tool_info(tool_def):
    bin_name = tool_def["bin"]
    paths = [f"/usr/local/bin/{bin_name}", f"/usr/bin/{bin_name}", f"/bin/{bin_name}"]
    found_path = ""
    for p in paths:
        if os.path.exists(p) and os.access(p, os.X_OK):
            found_path = p
            break
    if not found_path:
        w = subprocess.run(["which", bin_name], capture_output=True, text=True)
        if w.returncode == 0 and w.stdout.strip():
            found_path = w.stdout.strip()

    is_installed = bool(found_path)
    version_str = ""
    if is_installed:
        try:
            cmd = list(tool_def.get("cmd_ver", [found_path, "-v"]))
            cmd[0] = found_path
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=2)
            out = (r.stdout or r.stderr or "").strip()
            first_line = out.split("\n")[0] if out else "Installed"
            version_str = first_line[:45]
        except Exception:
            version_str = "نصب شده (Active)"
    else:
        version_str = "نصب نشده"

    return {
        "key": tool_def["key"],
        "name": tool_def["name"],
        "category": tool_def["category"],
        "desc": tool_def["desc"],
        "bin": bin_name,
        "installed": is_installed,
        "path": found_path,
        "version": version_str
    }

def install_tunnel_tool_binary(tool_key):
    bundle_dirs = ["/root/mhpanel-repo/bin", "/www/wwwroot/mhpanel/bin", "/usr/local/bin"]
    tool_def = next((t for t in TUNNEL_TOOLS_REGISTRY if t["key"] == tool_key), None)
    if not tool_def:
        return False, f"ابزار {tool_key} تعریف نشده است."

    bin_name = tool_def["bin"]
    target_path = f"/usr/local/bin/{bin_name}"

    if os.path.exists(target_path) and os.access(target_path, os.X_OK):
        return True, f"ابزار {bin_name} در حال حاضر نصب است."

    for bdir in bundle_dirs:
        candidate = os.path.join(bdir, bin_name)
        if os.path.exists(candidate) and os.path.isfile(candidate):
            try:
                subprocess.run(["cp", "-f", candidate, target_path], check=True)
                os.chmod(target_path, 0o755)
                return True, f"ابزار {bin_name} با موفقیت از پکیج به {target_path} منتقل و فعال شد."
            except Exception as e:
                return False, f"خطا در کپی باینری: {e}"

    if tool_key in ["openvpn", "wireguard"]:
        pkg = "openvpn" if tool_key == "openvpn" else "wireguard-tools"
        r = subprocess.run(["apt-get", "install", "-y", pkg], capture_output=True, text=True)
        if r.returncode == 0:
            return True, f"پکیج {pkg} با موفقیت توسط مخازن لینوکس نصب شد."
        else:
            return False, f"خطا در نصب apt: {r.stderr[:100]}"

    # Fallback: Automatic download from repository / release mirrors
    dl_scripts = {
        "gost": 'curl -fsSL https://github.com/go-gost/gost/releases/download/v3.0.0-rc10/gost_3.0.0-rc10_linux_amd64.tar.gz 2>/dev/null | tar -xz -C /usr/local/bin/ gost 2>/dev/null && chmod +x /usr/local/bin/gost',
        "wstunnel": 'curl -fsSL https://github.com/erebe/wstunnel/releases/download/v11.0.0/wstunnel_11.0.0_linux_amd64.tar.gz 2>/dev/null | tar -xz -C /usr/local/bin/ wstunnel 2>/dev/null && chmod +x /usr/local/bin/wstunnel',
        "chisel": 'curl -fsSL https://github.com/jpillora/chisel/releases/download/v1.10.0/chisel_1.10.0_linux_amd64.gz 2>/dev/null | gzip -d > /usr/local/bin/chisel 2>/dev/null && chmod +x /usr/local/bin/chisel',
        "rathole": 'curl -fsSL https://github.com/rapiz1/rathole/releases/download/v0.5.0/rathole-x86_64-unknown-linux-musl.zip -o /tmp/r.zip 2>/dev/null && unzip -o /tmp/r.zip -d /usr/local/bin/ 2>/dev/null && chmod +x /usr/local/bin/rathole && rm -f /tmp/r.zip',
        "udp2raw": 'curl -fsSL https://github.com/wangyu-/udp2raw/releases/download/20230206.0/udp2raw_binaries.tar.gz 2>/dev/null | tar -xz -C /tmp/ 2>/dev/null && mv /tmp/udp2raw_amd64 /usr/local/bin/udp2raw 2>/dev/null && chmod +x /usr/local/bin/udp2raw && rm -rf /tmp/udp2raw*',
        "rtt": 'curl -fsSL https://github.com/radkesvat/ReverseTlsTunnel/releases/download/v7.1/rtt-linux-amd64.zip -o /tmp/rtt.zip 2>/dev/null && unzip -o /tmp/rtt.zip -d /usr/local/bin/ 2>/dev/null && chmod +x /usr/local/bin/rtt && rm -f /tmp/rtt.zip',
        "dnstt": 'curl -fsSL https://raw.githubusercontent.com/t-51/MHPanel/main/bin/dnstt-server -o /usr/local/bin/dnstt-server 2>/dev/null && chmod +x /usr/local/bin/dnstt-server',
        "singbox": 'curl -fsSL "https://github.com/SagerNet/sing-box/releases/download/v1.9.3/sing-box-1.9.3-linux-amd64.tar.gz" 2>/dev/null | tar -xz -C /tmp/ 2>/dev/null && mv /tmp/sing-box-*/sing-box /usr/local/bin/sing-box 2>/dev/null && chmod +x /usr/local/bin/sing-box && rm -rf /tmp/sing-box*'
    }
    if tool_key in dl_scripts:
        try:
            subprocess.run(dl_scripts[tool_key], shell=True, timeout=60, check=True)
            if os.path.exists(target_path) and os.access(target_path, os.X_OK):
                return True, f"ابزار {bin_name} با موفقیت دانلود و در {target_path} فعال شد."
        except Exception as e:
            return False, f"خطا در دانلود خودکار {bin_name}: {e}"

    return False, f"فایل باینری {bin_name} یافت نشد."

@app.route("/api/tunnels/tools/status", methods=["GET"])
def api_tunnel_tools_status():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    results = [get_installed_tool_info(t) for t in TUNNEL_TOOLS_REGISTRY]
    installed_count = sum(1 for r in results if r["installed"])
    return jsonify({
        "success": True,
        "tools": results,
        "total": len(results),
        "installed_count": installed_count,
        "missing_count": len(results) - installed_count
    })

@app.route("/api/tunnels/tools/install", methods=["POST"])
def api_tunnel_tools_install():
    if not check_login():
        return jsonify({"error": "Unauthorized"}), 401
    req = request.get_json() or {}
    key = req.get("key")
    if not key:
        return jsonify({"error": "کلید ابزار مشخص نشده است."}), 400

    if key == "all_missing":
        installed_any = []
        for t in TUNNEL_TOOLS_REGISTRY:
            info = get_installed_tool_info(t)
            if not info["installed"]:
                ok, msg = install_tunnel_tool_binary(t["key"])
                if ok: installed_any.append(t["name"])
        return jsonify({"success": True, "installed": installed_any, "message": f"{len(installed_any)} ابزار مفقود با موفقیت نصب گردید."})

    ok, msg = install_tunnel_tool_binary(key)
    if not ok:
        return jsonify({"error": msg}), 500
    return jsonify({"success": True, "message": msg})

